1	{ config, lib, pkgs, cx, ... }:
2	let
3	  tenants = [ "amber" "cobalt" ];
4	  hello = user: pkgs.writeText "hello-${user}.py" ''
5	    #!/usr/bin/python3
6	    print("Content-Type: text/plain\n")
7	    print("hello from ${user}")
8	  '';
9	  php = pkgs.php.buildEnv {
10	    extensions = { enabled, all }: lib.unique (enabled ++ [
11	      all.pgsql all.pdo_pgsql all.mysqli all.pdo_mysql all.mbstring
12	    ]);
13	  };
14	  pool = user: {
15	    inherit user;
16	    group = user;
17	    phpPackage = php;
18	    settings = {
19	      "listen.owner" = "web";
20	      "listen.group" = "web";
21	      "listen.mode" = "0660";
22	      "pm" = "dynamic";
23	      "pm.max_children" = 10;
24	      "pm.start_servers" = 2;
25	      "pm.min_spare_servers" = 1;
26	      "pm.max_spare_servers" = 3;
27	      "pm.max_requests" = 10000;
28	      "request_terminate_timeout" = 180;
29	      "clear_env" = "yes";
30	      "env[HOME]" = "/home/${user}";
31	      "env[PATH]" = "/usr/local/bin:/usr/bin:/bin";
32	      "env[TMP]" = "/tmp";
33	      "env[TMPDIR]" = "/tmp";
34	      "env[NODE_LABEL]" = user;
35	      "php_value[max_execution_time]" = 120;
36	      "php_value[memory_limit]" = "128M";
37	      "php_value[post_max_size]" = if user == "amber" then "2M" else "8M";
38	      "php_value[upload_max_filesize]" = if user == "amber" then "2M" else "8M";
39	      "php_admin_value[open_basedir]" = "/home/${user}/:/tmp/:/usr/share/php/";
40	      "php_flag[display_errors]" = "off";
41	    };
42	  };
43	  tenantConfig = user:
44	    let source = builtins.replaceStrings [ "@USER@" ] [ user ]
45	      (builtins.readFile ./tenant.conf);
46	    in builtins.replaceStrings
47	      [ "/run/php/php-${user}-fpm.sock" "SetHandler cgi-script" ]
48	      [ config.services.phpfpm.pools.${user}.socket
49	        "ProxyFCGIBackendType GENERIC\n    SetHandler \"proxy:unix:/run/cgi-${user}.sock|fcgi://localhost\"" ]
50	      source;
51	  modules = [ "mpm_event" "unixd" "authn_core" "authz_core" "authz_host"
52	    "authn_file" "auth_basic" "authz_user" "access_compat" "mime" "dir"
53	    "autoindex" "alias" "env" "setenvif" "log_config" "ssl" "socache_shmcb"
54	    "rewrite" "headers" "proxy" "proxy_fcgi" "userdir" "include" ];
55	  apache = pkgs.writeText "node-httpd.conf" (''
56	    ServerRoot /run/node-httpd
57	    DefaultRuntimeDir /run/node-httpd
58	    PidFile /run/node-httpd/httpd.pid
59	    Listen 0.0.0.0:80
60	    Listen 0.0.0.0:443
61	  '' + lib.concatMapStringsSep "\n" (name:
62	    "LoadModule ${name}_module ${pkgs.apacheHttpd}/modules/mod_${name}.so"
63	  ) modules + ''
64	
65	    LoadModule wsgi_module ${pkgs.apacheHttpdPackages.mod_wsgi3}/modules/mod_wsgi.so
66	    WSGIPythonHome ${pkgs.python3}
67	    WSGISocketPrefix /run/node-httpd/wsgi
68	    User web
69	    Group web
70	    UserDir public_html
71	    UserDir disabled root
72	    ErrorLog /var/log/web/error.log
73	    TypesConfig ${pkgs.mailcap}/etc/mime.types
74	    DirectoryIndex index.html index.php
75	    LogFormat "%h %l %u %t \"%r\" %>s %b \"%{Referer}i\" \"%{User-Agent}i\"" combined
76	    <Directory />
77	      AllowOverride None
78	      Require all denied
79	    </Directory>
80	    ${builtins.readFile ./main.conf}
81	    ${lib.concatMapStringsSep "\n" tenantConfig tenants}
82	  '');
83	  postgresInit = pkgs.writeText "node-postgres.sql" (lib.concatMapStringsSep "\n" (user: ''
84	    CREATE ROLE ${user} LOGIN PASSWORD '${user}-pass';
85	    CREATE DATABASE ${user} OWNER ${user};
86	    REVOKE CONNECT ON DATABASE ${user} FROM PUBLIC;
87	    \connect ${user}
88	    CREATE EXTENSION postgis;
89	    \connect postgres
90	  '') tenants + cx.postgresSql);
91	  cgiService = user: {
92	    serviceConfig = {
93	      ExecStart = "${pkgs.fcgiwrap}/sbin/fcgiwrap -f";
94	      User = user;
95	      Group = user;
96	      StandardInput = "socket";
97	    };
98	  };
99	  mysqlInit = pkgs.writeText "node-mysql.sql" (lib.concatMapStringsSep "\n" (user: ''
