{ config, lib, pkgs, cx, ... }:
let
  tenants = [ "amber" "cobalt" ];
  hello = user: pkgs.writeText "hello-${user}.py" ''
    #!/usr/bin/python3
    print("Content-Type: text/plain\n")
    print("hello from ${user}")
  '';
  php = pkgs.php.buildEnv {
    extensions = { enabled, all }: lib.unique (enabled ++ [
      all.pgsql all.pdo_pgsql all.mysqli all.pdo_mysql all.mbstring
    ]);
  };
  pool = user: {
    inherit user;
    group = user;
    phpPackage = php;
    settings = {
      "listen.owner" = "web";
      "listen.group" = "web";
      "listen.mode" = "0660";
      "pm" = "dynamic";
      "pm.max_children" = 10;
      "pm.start_servers" = 2;
      "pm.min_spare_servers" = 1;
      "pm.max_spare_servers" = 3;
      "pm.max_requests" = 10000;
      "request_terminate_timeout" = 180;
      "clear_env" = "yes";
      "env[HOME]" = "/home/${user}";
      "env[PATH]" = "/usr/local/bin:/usr/bin:/bin";
      "env[TMP]" = "/tmp";
      "env[TMPDIR]" = "/tmp";
      "env[NODE_LABEL]" = user;
      "php_value[max_execution_time]" = 120;
      "php_value[memory_limit]" = "128M";
      "php_value[post_max_size]" = if user == "amber" then "2M" else "8M";
      "php_value[upload_max_filesize]" = if user == "amber" then "2M" else "8M";
      "php_admin_value[open_basedir]" = "/home/${user}/:/tmp/:/usr/share/php/";
      "php_flag[display_errors]" = "off";
    };
  };
  tenantConfig = user:
    let source = builtins.replaceStrings [ "@USER@" ] [ user ]
      (builtins.readFile ./tenant.conf);
    in builtins.replaceStrings
      [ "/run/php/php-${user}-fpm.sock" "SetHandler cgi-script" ]
      [ config.services.phpfpm.pools.${user}.socket
        "ProxyFCGIBackendType GENERIC\n    SetHandler \"proxy:unix:/run/cgi-${user}.sock|fcgi://localhost\"" ]
      source;
  modules = [ "mpm_event" "unixd" "authn_core" "authz_core" "authz_host"
    "authn_file" "auth_basic" "authz_user" "access_compat" "mime" "dir"
    "autoindex" "alias" "env" "setenvif" "log_config" "ssl" "socache_shmcb"
    "rewrite" "headers" "proxy" "proxy_fcgi" "userdir" "include" ];
  apache = pkgs.writeText "node-httpd.conf" (''
    ServerRoot /run/node-httpd
    DefaultRuntimeDir /run/node-httpd
    PidFile /run/node-httpd/httpd.pid
    Listen 0.0.0.0:80
    Listen 0.0.0.0:443
  '' + lib.concatMapStringsSep "\n" (name:
    "LoadModule ${name}_module ${pkgs.apacheHttpd}/modules/mod_${name}.so"
  ) modules + ''

    LoadModule wsgi_module ${pkgs.apacheHttpdPackages.mod_wsgi3}/modules/mod_wsgi.so
    WSGIPythonHome ${pkgs.python3}
    WSGISocketPrefix /run/node-httpd/wsgi
    User web
    Group web
    UserDir public_html
    UserDir disabled root
    ErrorLog /var/log/web/error.log
    TypesConfig ${pkgs.mailcap}/etc/mime.types
    DirectoryIndex index.html index.php
    LogFormat "%h %l %u %t \"%r\" %>s %b \"%{Referer}i\" \"%{User-Agent}i\"" combined
    <Directory />
      AllowOverride None
      Require all denied
    </Directory>
    ${builtins.readFile ./main.conf}
    ${lib.concatMapStringsSep "\n" tenantConfig tenants}
  '');
  postgresInit = pkgs.writeText "node-postgres.sql" (lib.concatMapStringsSep "\n" (user: ''
    CREATE ROLE ${user} LOGIN PASSWORD '${user}-pass';
    CREATE DATABASE ${user} OWNER ${user};
    REVOKE CONNECT ON DATABASE ${user} FROM PUBLIC;
    \connect ${user}
    CREATE EXTENSION postgis;
    \connect postgres
  '') tenants + cx.postgresSql);
  cgiService = user: {
    serviceConfig = {
      ExecStart = "${pkgs.fcgiwrap}/sbin/fcgiwrap -f";
      User = user;
      Group = user;
      StandardInput = "socket";
    };
  };
  mysqlInit = pkgs.writeText "node-mysql.sql" (lib.concatMapStringsSep "\n" (user: ''
    CREATE DATABASE ${user};
    CREATE USER '${user}'@'localhost' IDENTIFIED BY '${user}-pass';
    GRANT ALL ON ${user}.* TO '${user}'@'localhost';
  '') tenants + cx.mysqlSql);
in {
  imports = [ ./complexify.nix ];
  networking.hostName = "node17";
  networking.firewall.allowedTCPPorts = [ 22 80 443 ];
  networking.hosts."127.0.0.1" = [ "catalog.node.test" "sql.node.test" "cache.node.test" ];
  # Numeric ids match the reference so restored tenant data keeps its owners.
  users.groups = { amber.gid = 1000; cobalt.gid = 1001; web = {}; adm = {}; };
  users.users = lib.genAttrs tenants (user: {
    isNormalUser = true;
    uid = if user == "amber" then 1101 else 1102;
    home = "/home/${user}";
    createHome = true;
    group = user;
    shell = pkgs.bashInteractive;
  }) // { web = { isSystemUser = true; group = "web"; }; };
  environment.systemPackages = [ php config.services.postgresql.package pkgs.mariadb pkgs.memcached pkgs.acl ];
  systemd.slices."user-" = {
    overrideStrategy = "asDropin";
    sliceConfig = { MemoryHigh = "80%"; MemoryMax = "90%"; };
  };
  security.sudo = {
    enable = true;
    extraConfig = lib.concatMapStringsSep "\n" (user:
      "${user} ALL=(:adm) NOPASSWD: /bin/cat /var/log/web/${user}-access.log, /bin/cat /var/log/web/${user}-error.log"
    ) tenants;
  };
  systemd.tmpfiles.rules = [
    "d /usr/bin 0755 root root -"
    "L+ /usr/bin/python3 - - - - ${pkgs.python3}/bin/python3"
    "L+ /bin/cat - - - - ${pkgs.coreutils}/bin/cat"
  ];
  systemd.services.node-state = {
    wantedBy = [ "multi-user.target" ];
    before = [ "httpd.service" "phpfpm-amber.service" "phpfpm-cobalt.service" ];
    serviceConfig = { Type = "oneshot"; RemainAfterExit = true; };
    path = [ pkgs.coreutils ];
    script = ''
      install -d -m 0750 -o root -g adm /var/log/web
      install -d -m 0755 /srv/node
      test -e /srv/node/index.html || printf 'node service\n' > /srv/node/index.html
      ${lib.concatMapStringsSep "\n" (user: ''
        chmod 0755 /home/${user}
        for d in public_html public_html/cgi-bin public_html/wsgi-bin; do
          install -d -m 0755 -o ${user} -g ${user} /home/${user}/$d
        done
        install -d -m 0700 -o ${user} -g ${user} /home/${user}/private
        if [ ! -e /home/${user}/private/token ]; then
          printf '${user}-private\n' > /home/${user}/private/token
          chown ${user}:${user} /home/${user}/private/token
          chmod 0600 /home/${user}/private/token
        fi
        if [ ! -e /home/${user}/public_html/index.html ]; then
          printf '${user} workspace\n' > /home/${user}/public_html/index.html
          chown ${user}:${user} /home/${user}/public_html/index.html
        fi
        if [ ! -e /home/${user}/public_html/cgi-bin/hello.py ]; then
          install -m 0755 -o ${user} -g ${user} ${hello user} /home/${user}/public_html/cgi-bin/hello.py
        fi
        for kind in access error; do
          f=/var/log/web/${user}-$kind.log
          test -e "$f" || touch "$f"
          chown root:adm "$f"
          chmod 0640 "$f"
        done
      '') tenants}
    '';
  };
  services.phpfpm = { phpPackage = php; pools = lib.genAttrs tenants pool; };
  # NixOS pools default to ProtectHome; tenant docroots live under /home.
  systemd.services.phpfpm-amber.serviceConfig.ProtectHome = lib.mkForce false;
  systemd.services.phpfpm-cobalt.serviceConfig.ProtectHome = lib.mkForce false;
  services.postgresql = {
    enable = true;
    package = pkgs.postgresql_17;
    extensions = ps: [ ps.postgis ];
    authentication = lib.mkForce ''
      local all all peer
      host all all 127.0.0.1/32 scram-sha-256
      host all all ::1/128 scram-sha-256
    '';
    settings = { listen_addresses = lib.mkForce "127.0.0.1"; password_encryption = "scram-sha-256"; };
    initialScript = postgresInit;
  };
  services.mysql = {
    enable = true;
    package = pkgs.mariadb;
    initialScript = mysqlInit;
    settings.mysqld.bind-address = "127.0.0.1";
  };
  systemd.services.memcached = {
    wantedBy = [ "multi-user.target" ];
    serviceConfig = {
      ExecStart = "${pkgs.memcached}/bin/memcached -m 32 -p 11211 -l 127.0.0.1 -U 0";
      DynamicUser = true;
    };
  };
  systemd.services.httpd = {
    wantedBy = [ "multi-user.target" ];
    requires = [ "node-state.service" ];
    after = [ "node-state.service" "phpfpm-amber.service" "phpfpm-cobalt.service" "systemd-tmpfiles-setup.service" ];
    serviceConfig = {
      RuntimeDirectory = "node-httpd";
      ExecStart = "${pkgs.apacheHttpd}/bin/httpd -f ${apache} -DFOREGROUND";
      ExecReload = "${pkgs.apacheHttpd}/bin/httpd -f ${apache} -k graceful";
    };
  };
  # Nix uses per-user FastCGI sockets for CGI, preserving execution identity
  # without reproducing Ubuntu's distribution-specific suEXEC installation.
  systemd.sockets = lib.genAttrs (map (u: "cgi-${u}") tenants) (name:
    let user = lib.removePrefix "cgi-" name; in {
      wantedBy = [ "sockets.target" ];
      socketConfig = {
        ListenStream = "/run/${name}.sock";
        SocketUser = user;
        SocketGroup = "web";
        SocketMode = "0660";
      };
    });
  systemd.services.cgi-amber = cgiService "amber";
  systemd.services.cgi-cobalt = cgiService "cobalt";
}

"""Node17 verifier: recipe and complexifier checks; see author/methods.md and verification.md."""

import base64
import json
import os
import secrets
import shlex
import subprocess
import sys
import tempfile
import time
from pathlib import Path

LOG = Path("/logs/verifier")
USERS = ("amber", "cobalt")


def run(args, *, check=True, timeout=30, **kwargs):
    result = subprocess.run(args, check=False, capture_output=True, timeout=timeout, **kwargs)
    if check and result.returncode:
        detail = (result.stdout + result.stderr).decode(errors="replace")
        raise RuntimeError(f"Command {shlex.join(args)} exited {result.returncode}:\n{detail}")
    return result


def require(condition, detail):
    if not condition:
        raise AssertionError(str(detail))


class Guest:
    def __init__(self, candidate=False):
        self.ssh_port = 3222 if candidate else 2222
        self.http_port = 9080 if candidate else 8080
        self.https_port = 9443 if candidate else 8443

    def ssh(self, command, *, check=True, timeout=30):
        return run(
            ["/opt/runtime/guest", command],
            env=dict(os.environ, GUEST_SSH_PORT=str(self.ssh_port)),
            check=check,
            timeout=timeout,
        )

    def as_user(self, user, command, *, check=True):
        return self.ssh(f"runuser -u {user} -- sh -c {shlex.quote(command)}", check=check)

    def python(self, code):
        return self.ssh("python3 -c " + shlex.quote(code))

    def install(self, user, relative, content, *, executable=False):
        path = f"/home/{user}/public_html/{relative}"
        payload = base64.b64encode(content.encode()).decode()
        self.ssh(
            f"install -d -m 0755 -o {user} -g {user} {shlex.quote(str(Path(path).parent))}; "
            f"printf %s {payload} | base64 -d > {shlex.quote(path)}; "
            f"chown {user}:{user} {shlex.quote(path)}; chmod {'0755' if executable else '0644'} {shlex.quote(path)}"
        )

    def http(self, path="/", *, host="node.test", tls=True, headers=None):
        scheme, guest_port, port = ("https", 443, self.https_port) if tls else ("http", 80, self.http_port)
        with tempfile.TemporaryDirectory() as directory:
            header_file = Path(directory) / "headers"
            args = [
                "curl",
                "--silent",
                "--show-error",
                "--noproxy",
                "*",
                "--max-time",
                "15",
                "--cacert",
                "/opt/contract/ca.crt",
                "--connect-to",
                f"{host}:{guest_port}:127.0.0.1:{port}",
                "-D",
                str(header_file),
            ]
            for key, value in (headers or {}).items():
                args.extend(["-H", f"{key}: {value}"])
            response = run([*args, f"{scheme}://{host}{path}"])
            lines = header_file.read_text().splitlines()
            status = int(lines[0].split()[1])
            parsed = {
                key.lower(): value.strip() for line in lines[1:] if ":" in line for key, value in [line.split(":", 1)]
            }
            return status, parsed, response.stdout

    def php(self, user, token, code, *, headers=None):
        name = f"probe-{token}.php"
        self.install(user, name, '<?php header("Content-Type: application/json"); ' + code)
        status, _, body = self.http("/" + name, host=f"{user}.node.test", headers=headers)
        require(status == 200, (status, body.decode(errors="replace")))
        return json.loads(body)

    def ready(self):
        deadline = time.monotonic() + 180
        while time.monotonic() < deadline:
            result = self.ssh("systemctl is-active --quiet multi-user.target", check=False)
            if result.returncode == 0:
                return
            time.sleep(2)
        raise RuntimeError("Guest did not reach multi-user.target within 180 seconds")


def check(name, guest, token):
    if name == "host_resolution":
        require(guest.ssh("hostname").stdout.strip() == b"node17", "hostname")
        for host in ["catalog.node.test", "sql.node.test", "cache.node.test"]:
            result = guest.ssh(f"getent ahostsv4 {host}").stdout.decode().splitlines()
            require(result and all(line.split()[0] == "127.0.0.1" for line in result), host)
    elif name == "accounts":
        guest.python(
            "import grp,os,pwd\nfor u,uid,gid in [('amber',1101,1000),('cobalt',1102,1001)]:\n p=pwd.getpwnam(u); assert (p.pw_uid,p.pw_gid,p.pw_dir,os.path.basename(p.pw_shell),grp.getgrgid(gid).gr_name)==(uid,gid,'/home/'+u,'bash',u),p"
        )
    elif name == "filesystem_ownership":
        guest.python(
            "import os,pwd,stat;\nfor u in ('amber','cobalt'):\n for sub,mode in [('',0o755),('public_html',0o755),('public_html/cgi-bin',0o755),('public_html/wsgi-bin',0o755),('private',0o700),('private/token',0o600)]:\n  p='/home/'+u+'/'+sub; s=os.stat(p); assert pwd.getpwuid(s.st_uid).pw_name==u and stat.S_IMODE(s.st_mode)==mode,p"
        )
    elif name == "private_isolation":
        for user, other in [("amber", "cobalt"), ("cobalt", "amber")]:
            require(
                guest.as_user(user, f"cat /home/{user}/private/token").stdout.strip() == f"{user}-private".encode(),
                user,
            )
            require(
                guest.as_user(user, f"cat /home/{other}/private/token", check=False).returncode != 0,
                "cross-user private read",
            )
    elif name == "sudo_log_policy":
        for user, other in [("amber", "cobalt"), ("cobalt", "amber")]:
            guest.http("/", host=f"{user}.node.test")
            allowed = guest.as_user(user, f"sudo -n -g adm /bin/cat /var/log/web/{user}-access.log")
            require(bool(allowed.stdout), "own log empty")
            denied = guest.as_user(user, f"sudo -n -g adm /bin/cat /var/log/web/{other}-access.log", check=False)
            require(denied.returncode != 0, "sudo read other log")
            require(
                guest.as_user(user, f"cat /var/log/web/{user}-access.log", check=False).returncode != 0,
                "direct log read allowed",
            )
    elif name == "slice_limits":
        guest.python(
            "import os,pwd,subprocess; uid=pwd.getpwnam('amber').pw_uid; unit=f'user-{uid}.slice'; subprocess.run(['systemctl','start',unit],check=True); total=os.sysconf('SC_PHYS_PAGES')*os.sysconf('SC_PAGE_SIZE');\nfor prop,ratio in [('MemoryHigh',.8),('MemoryMax',.9)]:\n value=int(subprocess.check_output(['systemctl','show',unit,'--property='+prop,'--value'])); assert abs(value/total-ratio)<.01,(prop,value,total)"
        )
    elif name == "postgres_peer":
        for user in USERS:
            require(
                guest.as_user(user, f'psql -X -tAc "SELECT current_user,current_database()" {user}').stdout.strip()
                == f"{user}|{user}".encode(),
                user,
            )
    elif name == "postgres_password":
        for user in USERS:
            query = f'psql -X -h catalog.node.test -U {user} -d {user} -tAc "SELECT current_user"'
            require(guest.ssh(f"PGPASSWORD={user}-pass {query}").stdout.strip() == user.encode(), user)
            require(
                guest.ssh(f"PGPASSWORD=wrong {query}", check=False).returncode != 0, "bad postgres password accepted"
            )
        stored = guest.ssh(
            "cd / && runuser -u postgres -- psql -X -tAc \"SELECT rolname||':'||left(rolpassword,14) FROM pg_authid WHERE rolname IN ('amber','cobalt') ORDER BY 1\""
        ).stdout.split()
