52	    "authn_file" "auth_basic" "authz_user" "access_compat" "mime" "dir"
53	    "autoindex" "alias" "env" "setenvif" "log_config" "ssl" "socache_shmcb"
54	    "rewrite" "headers" "proxy" "proxy_fcgi" "userdir" "include" ];
55	  apache = pkgs.writeText "node-httpd.conf" (''
56	    ServerRoot /run/node-httpd
57	    DefaultRuntimeDir /run/node-httpd
58	    PidFile /run/node-httpd/httpd.pid
59	    Listen 0.0.0.0:80
60	    Listen 0.0.0.0:443
61	  '' + lib.concatMapStringsSep "\n" (name:
62	    "LoadModule ${name}_module ${pkgs.apacheHttpd}/modules/mod_${name}.so"
63	  ) modules + ''
64	
65	    LoadModule wsgi_module ${pkgs.apacheHttpdPackages.mod_wsgi3}/modules/mod_wsgi.so
66	    WSGIPythonHome ${pkgs.python3}
67	    WSGISocketPrefix /run/node-httpd/wsgi
68	    User web
69	    Group web
70	    UserDir public_html
71	    UserDir disabled root
72	    ErrorLog /var/log/web/error.log
73	    TypesConfig ${pkgs.mailcap}/etc/mime.types
74	    DirectoryIndex index.html index.php
75	    LogFormat "%h %l %u %t \"%r\" %>s %b \"%{Referer}i\" \"%{User-Agent}i\"" combined
76	    <Directory />
77	      AllowOverride None
78	      Require all denied
79	    </Directory>
80	    ${builtins.readFile ./main.conf}
81	    ${lib.concatMapStringsSep "\n" tenantConfig tenants}
82	  '');
83	  postgresInit = pkgs.writeText "node-postgres.sql" (lib.concatMapStringsSep "\n" (user: ''
84	    CREATE ROLE ${user} LOGIN PASSWORD '${user}-pass';
85	    CREATE DATABASE ${user} OWNER ${user};
86	    REVOKE CONNECT ON DATABASE ${user} FROM PUBLIC;
87	    \connect ${user}
88	    CREATE EXTENSION postgis;
89	    \connect postgres
90	  '') tenants + cx.postgresSql);
91	  cgiService = user: {
92	    serviceConfig = {
93	      ExecStart = "${pkgs.fcgiwrap}/sbin/fcgiwrap -f";
94	      User = user;
95	      Group = user;
96	      StandardInput = "socket";
97	    };
98	  };
99	  mysqlInit = pkgs.writeText "node-mysql.sql" (lib.concatMapStringsSep "\n" (user: ''
100	    CREATE DATABASE ${user};
101	    CREATE USER '${user}'@'localhost' IDENTIFIED BY '${user}-pass';
102	    GRANT ALL ON ${user}.* TO '${user}'@'localhost';
103	  '') tenants + cx.mysqlSql);
104	in {
105	  imports = [ ./complexify.nix ];
106	  networking.hostName = "node17";
107	  networking.firewall.allowedTCPPorts = [ 22 80 443 ];
108	  networking.hosts."127.0.0.1" = [ "catalog.node.test" "sql.node.test" "cache.node.test" ];
109	  # Numeric ids match the reference so restored tenant data keeps its owners.
110	  users.groups = { amber.gid = 1000; cobalt.gid = 1001; web = {}; adm = {}; };
111	  users.users = lib.genAttrs tenants (user: {
112	    isNormalUser = true;
113	    uid = if user == "amber" then 1101 else 1102;
114	    home = "/home/${user}";
115	    createHome = true;
116	    group = user;
117	    shell = pkgs.bashInteractive;
118	  }) // { web = { isSystemUser = true; group = "web"; }; };
119	  environment.systemPackages = [ php config.services.postgresql.package pkgs.mariadb pkgs.memcached pkgs.acl ];
120	  systemd.slices."user-" = {
121	    overrideStrategy = "asDropin";
122	    sliceConfig = { MemoryHigh = "80%"; MemoryMax = "90%"; };
123	  };
124	  security.sudo = {
125	    enable = true;
126	    extraConfig = lib.concatMapStringsSep "\n" (user:
127	      "${user} ALL=(:adm) NOPASSWD: /bin/cat /var/log/web/${user}-access.log, /bin/cat /var/log/web/${user}-error.log"
128	    ) tenants;
129	  };
130	  systemd.tmpfiles.rules = [
131	    "d /usr/bin 0755 root root -"
132	    "L+ /usr/bin/python3 - - - - ${pkgs.python3}/bin/python3"
133	    "L+ /bin/cat - - - - ${pkgs.coreutils}/bin/cat"
134	  ];
135	  systemd.services.node-state = {
136	    wantedBy = [ "multi-user.target" ];
137	    before = [ "httpd.service" "phpfpm-amber.service" "phpfpm-cobalt.service" ];
138	    serviceConfig = { Type = "oneshot"; RemainAfterExit = true; };
139	    path = [ pkgs.coreutils ];
140	    script = ''
141	      install -d -m 0750 -o root -g adm /var/log/web
142	      install -d -m 0755 /srv/node
143	      test -e /srv/node/index.html || printf 'node service\n' > /srv/node/index.html
144	      ${lib.concatMapStringsSep "\n" (user: ''
145	        chmod 0755 /home/${user}
146	        for d in public_html public_html/cgi-bin public_html/wsgi-bin; do
147	          install -d -m 0755 -o ${user} -g ${user} /home/${user}/$d
148	        done
149	        install -d -m 0700 -o ${user} -g ${user} /home/${user}/private
150	        if [ ! -e /home/${user}/private/token ]; then
151	          printf '${user}-private\n' > /home/${user}/private/token
152	          chown ${user}:${user} /home/${user}/private/token
153	          chmod 0600 /home/${user}/private/token
154	        fi
155	        if [ ! -e /home/${user}/public_html/index.html ]; then
156	          printf '${user} workspace\n' > /home/${user}/public_html/index.html
157	          chown ${user}:${user} /home/${user}/public_html/index.html
158	        fi
159	        if [ ! -e /home/${user}/public_html/cgi-bin/hello.py ]; then
160	          install -m 0755 -o ${user} -g ${user} ${hello user} /home/${user}/public_html/cgi-bin/hello.py
161	        fi
162	        for kind in access error; do
163	          f=/var/log/web/${user}-$kind.log
164	          test -e "$f" || touch "$f"
165	          chown root:adm "$f"
166	          chmod 0640 "$f"
167	        done
168	      '') tenants}
169	    '';
170	  };
171	  services.phpfpm = { phpPackage = php; pools = lib.genAttrs tenants pool; };
172	  # NixOS pools default to ProtectHome; tenant docroots live under /home.
173	  systemd.services.phpfpm-amber.serviceConfig.ProtectHome = lib.mkForce false;
174	  systemd.services.phpfpm-cobalt.serviceConfig.ProtectHome = lib.mkForce false;
175	  services.postgresql = {
176	    enable = true;
177	    package = pkgs.postgresql_17;
178	    extensions = ps: [ ps.postgis ];
179	    authentication = lib.mkForce ''
180	      local all all peer
181	      host all all 127.0.0.1/32 scram-sha-256
182	      host all all ::1/128 scram-sha-256
183	    '';
184	    settings = { listen_addresses = lib.mkForce "127.0.0.1"; password_encryption = "scram-sha-256"; };
185	    initialScript = postgresInit;
186	  };
187	  services.mysql = {
188	    enable = true;
189	    package = pkgs.mariadb;
190	    initialScript = mysqlInit;
191	    settings.mysqld.bind-address = "127.0.0.1";
192	  };
193	  systemd.services.memcached = {
194	    wantedBy = [ "multi-user.target" ];
195	    serviceConfig = {
196	      ExecStart = "${pkgs.memcached}/bin/memcached -m 32 -p 11211 -l 127.0.0.1 -U 0";
197	      DynamicUser = true;
198	    };
199	  };
200	  systemd.services.httpd = {
201	    wantedBy = [ "multi-user.target" ];
202	    requires = [ "node-state.service" ];
203	    after = [ "node-state.service" "phpfpm-amber.service" "phpfpm-cobalt.service" "systemd-tmpfiles-setup.service" ];
204	    serviceConfig = {
205	      RuntimeDirectory = "node-httpd";
206	      ExecStart = "${pkgs.apacheHttpd}/bin/httpd -f ${apache} -DFOREGROUND";
207	      ExecReload = "${pkgs.apacheHttpd}/bin/httpd -f ${apache} -k graceful";
208	    };
209	  };
210	  # Nix uses per-user FastCGI sockets for CGI, preserving execution identity
211	  # without reproducing Ubuntu's distribution-specific suEXEC installation.
212	  systemd.sockets = lib.genAttrs (map (u: "cgi-${u}") tenants) (name:
213	    let user = lib.removePrefix "cgi-" name; in {
214	      wantedBy = [ "sockets.target" ];
215	      socketConfig = {
216	        ListenStream = "/run/${name}.sock";
217	        SocketUser = user;
218	        SocketGroup = "web";
219	        SocketMode = "0660";
220	      };
221	    });
222	  systemd.services.cgi-amber = cgiService "amber";
223	  systemd.services.cgi-cobalt = cgiService "cobalt";
224	}
